cat > /work/src/pages/ProductPage.css <<'EOF'
* { box-sizing: border-box; }

.store {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  color: #1c1c1c;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

.store-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid #e4e4e4;
}

.store-logo h1 {
  margin: 0;
  font-size: 26px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #1c1c1c;
  text-decoration: none;
}

.cart-link { font-size: 15px; color: #1c1c1c; text-decoration: none; }
.cart-link:hover { text-decoration: underline; }

.breadcrumbs ol {
  list-style: none;
  display: flex;
  gap: 8px;
  padding: 14px 0;
  margin: 0;
  font-size: 14px;
  color: #6c6c6c;
}
.breadcrumbs li + li::before { content: '/'; margin-right: 8px; color: #b5b5b5; }
.breadcrumbs a { color: #2b5f9e; text-decoration: none; }
.breadcrumbs a:hover { text-decoration: underline; }

.product {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  padding: 16px 0 40px;
}

.gallery {
  position: relative;
  background: #eef1f5;
  border-radius: 12px;
  overflow: hidden;
}
.photo { width: 100%; height: auto; display: block; }
.photo-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 42px;
  height: 42px;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  font-size: 22px;
  cursor: pointer;
}
.photo-nav.prev { left: 12px; }
.photo-nav.next { right: 12px; }
.photo-nav:hover { background: #fff; }
.photo-count {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  font-size: 13px;
  color: #555;
}

.details h2 { margin: 0 0 6px; font-size: 32px; }
.tagline { margin: 0 0 18px; color: #6c6c6c; }

.price-row { display: flex; align-items: center; gap: 8px; margin-bottom: 24px; }
.price { font-size: 22px; font-weight: 700; }
.price-info {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid #999;
  font-size: 12px;
  font-style: italic;
  color: #666;
  cursor: help;
}
.price-tooltip {
  position: absolute;
  bottom: 26px;
  left: -10px;
  background: #1c1c1c;
  color: #fff;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 13px;
  white-space: nowrap;
  z-index: 5;
}
.price-tooltip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 14px;
  border: 6px solid transparent;
  border-top-color: #1c1c1c;
}

fieldset { border: none; padding: 0; margin: 0 0 20px; }
legend { font-size: 14px; font-weight: 600; margin-bottom: 8px; }

.swatches { display: flex; gap: 14px; }
.swatch-label { display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 14px; }
