function SizeGuideModal({ onClose, onPickSize }) {
  const [footLength, setFootLength] = useState('')
  const [system, setSystem] = useState('us')

  const recommended = (() => {
    const cm = Number(footLength)
    if (!Number.isFinite(cm) || cm <= 0) return null
    const us = Math.round((cm - 21.5) * 1.5 * 2) / 2
    if (system === 'us') return us
    return Math.round(us + 33.5)
  })()

  return (
    <div className="modal-overlay">
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-label="Size guide"
      >
        <h2>Size guide</h2>
        <p>Enter your foot length in centimetres to find your size.</p>
        <label htmlFor="foot-length">Foot length (cm)</label>
        <input
          id="foot-length"
          type="number"
          step="0.5"
          min="10"
          max="35"
          value={footLength}
          onChange={(e) => setFootLength(e.target.value)}
        />
        <fieldset>
          <legend>Size system</legend>
          <label>
            <input
              type="radio"
              name="system"
              value="us"
              checked={system === 'us'}
              onChange={() => setSystem('us')}
            />{' '}
            US
          </label>
          <label>
            <input
              type="radio"
              name="system"
              value="eu"
              checked={system === 'eu'}
              onChange={() => setSystem('eu')}
            />{' '}
            EU
          </label>
        </fieldset>
        <p className="recommended-size">
          {recommended
            ? `Your recommended size: ${recommended} ${
                system === 'us' ? 'US' : 'EU'
              }`
            : 'Enter a foot length to see your size.'}
        </p>
        <div className="modal-actions">
          {recommended && (
            <button type="button" onClick={() => onPickSize(recommended)}>
              Use this size
            </button>
          )}
          <button type="button" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  )
}

