* { box-sizing: border-box; }

.store {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  color: #1c1c1c;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

.store-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid #e4e4e4;
}

.store-logo h1 {
  margin: 0;
  font-size: 26px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #1c1c1c;
  text-decoration: none;
}

.cart-link { font-size: 15px; color: #1c1c1c; text-decoration: none; }
.cart-link:hover { text-decoration: underline; }

.breadcrumbs ol {
  list-style: none;
  display: flex;
  gap: 8px;
  padding: 14px 0;
  margin: 0;
  font-size: 14px;
  color: #6c6c6c;
}
.breadcrumbs li + li::before { content: '/'; margin-right: 8px; color: #b5b5b5; }
.breadcrumbs a { color: #2b5f9e; text-decoration: none; }
.breadcrumbs a:hover { text-decoration: underline; }

.product {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  padding: 16px 0 40px;
}

.gallery {
  position: relative;
  background: #eef1f5;
  border-radius: 12px;
  overflow: hidden;
}
.photo { width: 100%; height: auto; display: block; }
.photo-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 42px;
  height: 42px;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  font-size: 22px;
  cursor: pointer;
}
.photo-nav.prev { left: 12px; }
.photo-nav.next { right: 12px; }
.photo-nav:hover { background: #fff; }
.photo-count {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  font-size: 13px;
  color: #555;
}

.details h2 { margin: 0 0 6px; font-size: 32px; }
.tagline { margin: 0 0 18px; color: #6c6c6c; }

.price-row { display: flex; align-items: center; gap: 8px; margin-bottom: 24px; }
.price { font-size: 22px; font-weight: 700; }
.price-info {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid #999;
  font-size: 12px;
  font-style: italic;
  color: #666;
  cursor: help;
}
.price-tooltip {
  position: absolute;
  bottom: 26px;
  left: -10px;
  background: #1c1c1c;
  color: #fff;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 13px;
  white-space: nowrap;
  z-index: 5;
}
.price-tooltip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 14px;
  border: 6px solid transparent;
  border-top-color: #1c1c1c;
}

fieldset { border: none; padding: 0; margin: 0 0 20px; }
legend { font-size: 14px; font-weight: 600; margin-bottom: 8px; }

.swatches { display: flex; gap: 14px; }
.swatch-label { display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 14px; }
.swatch-label input { position: absolute; opacity: 0; pointer-events: none; }
.swatch {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: inline-block;
  border: 2px solid transparent;
  box-shadow: inset 0 0 0 2px #fff;
}
.swatch-label input:checked + .swatch { border-color: #1c1c1c; }
.swatch-label input:focus-visible + .swatch { outline: 2px solid #2b5f9e; }

.size-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 10px;
}
.size-row label { font-size: 14px; font-weight: 600; }
.size-select {
  flex: 1;
  padding: 10px 12px;
  font-size: 15px;
  border: 1px solid #c9c9c9;
  border-radius: 6px;
  background: #fff;
}
.size-guide-button {
  border: none;
  background: none;
  color: #2b5f9e;
  text-decoration: underline;
  cursor: pointer;
  font-size: 14px;
}

.error { color: #b3261e; font-size: 14px; margin: 0 0 14px; }

.quantity-row { display: flex; align-items: center; gap: 12px; margin-bottom: 24px; }
.quantity-row label { font-size: 14px; font-weight: 600; }
.stepper { display: flex; align-items: center; border: 1px solid #c9c9c9; border-radius: 6px; overflow: hidden; }
.stepper button {
  width: 38px;
  height: 40px;
  border: none;
  background: #f5f5f5;
  font-size: 18px;
  cursor: pointer;
}
.stepper input {
  width: 56px;
  height: 40px;
  border: none;
  text-align: center;
  font-size: 15px;
}

.actions { display: flex; gap: 12px; margin-bottom: 12px; }
.add-to-cart {
  flex: 1;
  padding: 14px 20px;
  background: #2b5f9e;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
}
.add-to-cart:hover { background: #24507f; }
.wishlist {
  width: 52px;
  font-size: 24px;
  border: 1px solid #c9c9c9;
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
}
.wishlist[aria-pressed='true'] { color: #d0342c; border-color: #d0342c; }

.confirmation { color: #1c7a43; font-size: 14px; margin: 0 0 18px; }

.tablist { display: flex; gap: 4px; border-bottom: 1px solid #ddd; margin-top: 10px; }
.tablist button {
  border: none;
  background: none;
  padding: 10px 16px;
  font-size: 15px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
}
.tablist button[aria-selected='true'] { border-bottom-color: #1c1c1c; font-weight: 600; }
.tabpanel { padding: 16px 4px; font-size: 15px; line-height: 1.6; }
.tabpanel ul { margin: 0; padding-left: 18px; }

.questions { padding: 10px 0 40px; max-width: 720px; }
.questions h2 { font-size: 22px; margin: 0 0 12px; }
.question { border-top: 1px solid #e4e4e4; }
.question:last-child { border-bottom: 1px solid #e4e4e4; }
.question button {
  width: 100%;
  text-align: left;
  padding: 14px 4px;
  border: none;
  background: none;
  font-size: 16px;
  cursor: pointer;
}
.question button::after { content: '+'; float: right; color: #888; }
.question button[aria-expanded='true']::after { content: '−'; }
.question [role='region'] { padding: 0 4px 16px; color: #555; font-size: 15px; line-height: 1.6; }

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
}
.modal {
  background: #fff;
  border-radius: 12px;
  padding: 24px;
  width: min(420px, 90vw);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}
.modal h2 { margin: 0 0 8px; font-size: 22px; }
.modal p { font-size: 14px; color: #555; }
.modal label { display: block; font-size: 14px; margin: 12px 0 4px; }
.modal input[type='number'] {
  width: 100%;
  padding: 9px 10px;
  font-size: 15px;
  border: 1px solid #c9c9c9;
  border-radius: 6px;
}
.modal fieldset legend { margin: 12px 0 4px; }
.modal fieldset label { display: inline-flex; align-items: center; gap: 6px; margin: 8px 12px 0 0; }
.recommended-size { font-weight: 600; color: #1c1c1c; margin-top: 16px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }
.modal-actions button {
  padding: 10px 16px;
  border-radius: 6px;
  border: 1px solid #c9c9c9;
  background: #fff;
  font-size: 15px;
  cursor: pointer;
}
.modal-actions button:first-child { background: #2b5f9e; border-color: #2b5f9e; color: #fff; }

.footer {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  border-top: 1px solid #e4e4e4;
  padding: 28px 0 40px;
  font-size: 14px;
}
.footer h3 { font-size: 15px; margin: 0 0 10px; }
.footer ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.footer a { color: #444; text-decoration: none; }
.footer a:hover { text-decoration: underline; }

@media (max-width: 820px) {
  .product { grid-template-columns: 1fr; gap: 24px; }
  .footer { grid-template-columns: 1fr; }
}

